You can use the low-level `Audio::FAudioCapture` API from the Audio Capture Core module. One important caveat: `AGameMode` exists only on the server in a networked game. Microphone capture normally needs to run on the local client; for multiplayer, put it in a client-side object such as a subsystem or PlayerController instead. The example below is for a standalone game.

Enable the **Audio Capture** plugin and add `AudioCaptureCore` to your module dependencies in `YourProject.Build.cs` (for example, in `PublicDependencyModuleNames` if the header is included below).

**MyGameMode.h**
```cpp
#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "AudioCaptureCore.h"
#include "Containers/Queue.h"
#include "MyGameMode.generated.h"

UCLASS()
class YOURPROJECT_API AMyGameMode : public AGameModeBase
{
    GENERATED_BODY()

public:
    virtual void BeginPlay() override;
    virtual void Tick(float DeltaSeconds) override;
    virtual void EndPlay(const EEndPlayReason::Type EndPlayReason) override;

private:
    void StartCapture();
    void StopCapture();

    Audio::FAudioCapture Capture;
    bool bStreamOpen = false;

    // The capture callback runs off the game thread; queue chunks for Tick().
    TQueue<TArray<float>, EQueueMode::Mpsc> PendingAudio;
};
```

**MyGameMode.cpp**
```cpp
#include "MyGameMode.h"

void AMyGameMode::BeginPlay()
{
    Super::BeginPlay();
    StartCapture();
}

void AMyGameMode::StartCapture()
{
    Audio::FAudioCaptureDeviceParams Params;
    Params.DeviceIndex = INDEX_NONE;       // Default input device
    Params.NumInputChannels = 1;
    Params.SampleRate = 48000;

    const bool bOpened = Capture.OpenAudioCaptureStream(
        Params,
        [this](const float* AudioData,
               int32 NumFrames,
               int32 NumChannels,
               int32 SampleRate,
               double StreamTime,
               bool bOverflow)
        {
            // This callback is not on the game thread. Avoid touching UObjects here.
            if (AudioData && NumFrames > 0 && NumChannels > 0)
            {
                TArray<float> Chunk;
                Chunk.Append(AudioData, NumFrames * NumChannels);
                PendingAudio.Enqueue(MoveTemp(Chunk));
            }
        },
        1024); // Desired frames per callback

    if (!bOpened)
    {
        UE_LOG(LogTemp, Error, TEXT("Could not open the audio capture stream."));
        return;
    }

    bStreamOpen = true;
    if (!Capture.StartStream())
    {
        UE_LOG(LogTemp, Error, TEXT("Could not start the audio capture stream."));
        StopCapture();
    }
}

void AMyGameMode::Tick(float DeltaSeconds)
{
    Super::Tick(DeltaSeconds);

    TArray<float> Chunk;
    while (PendingAudio.Dequeue(Chunk))
    {
        // Process this chunk on the game thread.
        // Chunk contains interleaved float samples.
    }
}

void AMyGameMode::StopCapture()
{
    if (bStreamOpen)
    {
        Capture.StopStream();
        Capture.CloseStream();
        bStreamOpen = false;
    }
}

void AMyGameMode::EndPlay(const EEndPlayReason::Type EndPlayReason)
{
    StopCapture();
    Super::EndPlay(EndPlayReason);
}
```

Check the exact API names against the UE5 version you are using, since Audio Capture APIs can vary between engine versions. Also ensure the target platform supports audio input and that the application has microphone permission.

