### 我对题目的回答

可以用阶乘数系统逐位确定排列中的数字。每个首位数字对应 \((n-1)!\) 个排列，因此将 \(k\) 转为从 0 开始的索引后，就能计算出每一位应选剩余数字中的哪一个。

```cpp
#include <string>
#include <vector>

class Solution {
public:
    std::string getPermutation(int n, int k) {
        std::vector<int> factorial(n + 1, 1);
        for (int i = 1; i <= n; ++i) {
            factorial[i] = factorial[i - 1] * i;
        }

        std::vector<int> digits;
        for (int i = 1; i <= n; ++i) {
            digits.push_back(i);
        }

        --k;  // 转成 0-based 索引
        std::string result;

        for (int remaining = n; remaining >= 1; --remaining) {
            int blockSize = factorial[remaining - 1];
            int index = k / blockSize;

            result += std::to_string(digits[index]);
            digits.erase(digits.begin() + index);
            k %= blockSize;
        }

        return result;
    }
};
